/**
 * Queue, deque and queue-driven BFS interview problems tagged with the companies that publicly report them.
 *
 * Large "performance" inputs are generated deterministically by the seeded PRNG below; their expected outputs are
 * literals produced by independent brute-force implementations (not by the reference solutions).
 */

import { code, type ProblemSpec } from "../../problemHelpers";

/** Deterministic PRNG (mulberry32): returns an integer in [0, bound). */
function seededRandom(seed: number): (bound: number) => number {
  let state = seed >>> 0;
  return (bound: number) => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return Math.floor((((t ^ (t >>> 14)) >>> 0) / 4294967296) * bound);
  };
}

// 4000 strictly increasing request timestamps (gaps 1..15 ms): the 3000 ms window holds a few hundred pings.
const RECENT_CALLS_PERF = (() => {
  const next = seededRandom(11);
  const times: number[] = [];
  let t = 0;
  for (let i = 0; i < 4000; i++) {
    t += 1 + next(15);
    times.push(t);
  }
  return times.join(" ");
})();

const REVERSE_K_PERF = (() => {
  const next = seededRandom(12);
  return Array.from({ length: 2000 }, () => next(2001) - 1000).join(" ") + "\n1234";
})();

const TICKETS_PERF = (() => {
  const next = seededRandom(13);
  return Array.from({ length: 1000 }, () => 1 + next(1000)).join(" ") + "\n777";
})();

const LUNCH_PERF = (() => {
  const next = seededRandom(14);
  const students = Array.from({ length: 10000 }, () => next(2));
  const sandwiches = Array.from({ length: 10000 }, () => next(2));
  return students.join(" ") + "\n" + sandwiches.join(" ");
})();

const STACK_PERF = (() => {
  const next = seededRandom(15);
  const ops: string[] = [];
  let size = 0;
  for (let i = 0; i < 3000; i++) {
    const r = next(10);
    if (size === 0 || r < 5) {
      ops.push(`push ${next(2001) - 1000}`);
      size++;
    } else if (r < 8) {
      ops.push("pop");
      size--;
    } else if (r < 9) ops.push("top");
    else ops.push("empty");
  }
  return ops.join("\n");
})();

const INTERLEAVE_PERF = (() => {
  const next = seededRandom(16);
  return Array.from({ length: 2000 }, () => next(100001) - 50000).join(" ");
})();

// Mostly three hot letters, with a rare letter now and then so the first unique character keeps changing.
const STREAM_PERF = (() => {
  const next = seededRandom(17);
  const letters = "abcdefghijklmnopqrstuvwxyz";
  let out = "";
  for (let i = 0; i < 6000; i++) out += next(100) < 97 ? "abc"[next(3)] : letters[next(26)];
  return out;
})();

