        function solve(input) {
          const a = input.trim().split(/\s+/);
          const half = a.length / 2;
          const helper = a.slice(0, half);
          const main = a.slice(half);
          const out = [];
          let head = 0;
          for (let i = 0; i < half; i++) {
            out.push(helper[i]);
            out.push(main[head++]);
          }
          return out.join(" ");
        }
